SELECT id, config_id, config_name, description, agent_id, config_data, version, status, create_by, update_by, create_time, update_time
FROM ai_agent_draw_config
WHERE config_id = #{configId}

SELECT id, config_id, config_name, description, agent_id, config_data, version, status, create_by, update_by, create_time, update_time
FROM ai_agent_draw_config
WHERE agent_id = #{agentId}
